
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_pbe_gx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_pbe_gx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.079545282174058e+00, -4.974867420995601e+00, -4.828092274560957e+00, -4.624566666026943e+00, -4.346792648853436e+00, -3.976120280159906e+00, -3.496839201918152e+00, -2.903376179542505e+00, -2.209009675215866e+00, -1.445932695900168e+00, -7.572262277576136e-01, -6.215737795162186e-01, -6.457527376576077e-01, -5.390942451717190e-01, -3.556520657130663e-01, -1.741188000806371e-01, -4.809333618591714e-02, -3.848939604537676e-03, -4.461471237080062e-05, -6.517027024076547e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


